// Kotlin port of ios/TwistedTacKit/Sources/TwistedTacKit/GameRules.swift, itself a
// port of supabase/functions/_shared/gameRules.ts — the canonical rules.
// The server stays authoritative; this engine drives local play, optimistic
// online moves and the AI. Parity with the TypeScript engine is enforced by
// ParityTests, which replay vectors generated by scripts/gen-parity-vectors.ts.

package com.twistedtac.engine

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

@Serializable
enum class Player {
    X,
    O;

    val opponent: Player get() = if (this == X) O else X
}

@Serializable
enum class ViewMode {
    @SerialName("2D") FLAT,
    @SerialName("3D") CUBE,
}

/** One entry per cell, row-major within a layer, layer 0 first. Null is empty. */
typealias Board = List<Player?>

@Serializable
data class LayerResult(val winner: Player? = null, val line: List<Int>? = null)

/** A line of cells that wins when one player holds all of them. */
class BoardLine(
    val cells: List<Int>,
    /** Cross-layer lines end the match outright, so the AI weights them higher. */
    val cross: Boolean,
)

/** Every line on the board plus per-cell lookups, built once per config. */
class LineIndex(
    val all: List<BoardLine>,
    /** Cell index -> how many lines pass through it; used for move ordering. */
    val weightByCell: IntArray,
)

class GameRulesConfig private constructor(val size: Int, val viewMode: ViewMode) {
    val is3D: Boolean = viewMode == ViewMode.CUBE
    val winLength: Int = size
    val layerCount: Int = if (is3D) size else 1
    val cellsPerLayer: Int = size * size
    val cellCount: Int = if (is3D) size * size * size else size * size
    val matchWinThreshold: Int = if (is3D && size > 1) size - 1 else 0

    /** Row, column and diagonal lines of each layer, indexed by layer. */
    val layerLines: List<List<List<Int>>> =
        (0 until layerCount).map { makeLayerLines(size, it * cellsPerLayer) }

    /** Lines through the stack. Empty unless the board is 3D and larger than 1. */
    val crossLayerLines: List<List<Int>> =
        if (is3D && size > 1) makeCrossLayerLines(size) else emptyList()

    val lineIndex: LineIndex

    init {
        val all = crossLayerLines.map { BoardLine(it, cross = true) } +
            layerLines.flatMap { lines -> lines.map { BoardLine(it, cross = false) } }
        val weights = IntArray(cellCount)
        for (line in all) for (cell in line.cells) weights[cell] += 1
        lineIndex = LineIndex(all, weights)
    }

    fun index(x: Int, y: Int, z: Int): Int = x + y * size + z * cellsPerLayer
    fun layerOf(cellIndex: Int): Int = cellIndex / cellsPerLayer

    override fun equals(other: Any?): Boolean =
        other is GameRulesConfig && size == other.size && viewMode == other.viewMode

    override fun hashCode(): Int = 31 * size + viewMode.hashCode()

    companion object {
        /** Boards are 1x1(x1) through 8x8(x8); anything else is rejected. */
        fun of(size: Int, viewMode: ViewMode): GameRulesConfig? =
            if (size in 1..8) GameRulesConfig(size, viewMode) else null

        private fun makeLayerLines(size: Int, offset: Int): List<List<Int>> {
            val lines = mutableListOf<List<Int>>()
            for (y in 0 until size) lines.add((0 until size).map { offset + y * size + it })
            for (x in 0 until size) lines.add((0 until size).map { offset + it * size + x })
            lines.add((0 until size).map { offset + it * size + it })
            lines.add((0 until size).map { offset + it * size + (size - 1 - it) })
            return lines
        }

        private fun makeCrossLayerLines(size: Int): List<List<Int>> {
            val layer = size * size
            fun index(x: Int, y: Int, z: Int) = x + y * size + z * layer
            val lines = mutableListOf<List<Int>>()

            for (x in 0 until size) {
                for (y in 0 until size) lines.add((0 until size).map { index(x, y, it) })
            }
            for (y in 0 until size) {
                lines.add((0 until size).map { index(it, y, it) })
                lines.add((0 until size).map { index(size - 1 - it, y, it) })
            }
            for (x in 0 until size) {
                lines.add((0 until size).map { index(x, it, it) })
                lines.add((0 until size).map { index(x, size - 1 - it, it) })
            }
            lines.add((0 until size).map { index(it, it, it) })
            lines.add((0 until size).map { index(size - 1 - it, it, it) })
            lines.add((0 until size).map { index(it, size - 1 - it, it) })
            lines.add((0 until size).map { index(size - 1 - it, size - 1 - it, it) })
            return lines
        }
    }
}

data class GameState(val board: Board, val layerWinners: List<LayerResult>) {
    constructor(config: GameRulesConfig) : this(
        board = List(config.cellCount) { null },
        layerWinners = List(config.layerCount) { LayerResult() },
    )
}

data class LineWin(val winner: Player?, val line: List<Int>?)

private val NO_WIN = LineWin(null, null)

private fun checkLinesWinner(board: Board, lines: List<List<Int>>, winLength: Int): LineWin {
    for (line in lines) {
        if (line.size < winLength) continue
        val first = board[line[0]] ?: continue
        if (line.all { board[it] == first }) return LineWin(first, line)
    }
    return NO_WIN
}

fun checkCrossLayerWinner(config: GameRulesConfig, board: Board): LineWin {
    if (!config.is3D || config.size <= 1) return NO_WIN
    return checkLinesWinner(board, config.crossLayerLines, config.winLength)
}

fun checkLayerWinner(config: GameRulesConfig, board: Board, layer: Int): LineWin =
    checkLinesWinner(board, config.layerLines[layer], config.winLength)

fun checkBoardWinner(config: GameRulesConfig, board: Board): LineWin =
    checkLayerWinner(config, board, 0)

fun isLayerFull(config: GameRulesConfig, board: Board, layer: Int): Boolean {
    val offset = layer * config.cellsPerLayer
    for (i in 0 until config.cellsPerLayer) if (board[offset + i] == null) return false
    return true
}

fun isValidBoardState(config: GameRulesConfig, board: Board): Boolean = board.size == config.cellCount

fun isValidLayerResults(config: GameRulesConfig, layerWinners: List<LayerResult>): Boolean =
    layerWinners.size == config.layerCount

/** True while at least one empty cell sits on a layer nobody has claimed. */
fun hasLegalMoves(config: GameRulesConfig, board: Board, layerWinners: List<LayerResult>): Boolean {
    for (i in 0 until config.cellCount) {
        if (board[i] != null) continue
        if (layerWinners[config.layerOf(i)].winner != null) continue
        return true
    }
    return false
}

fun legalMoves(config: GameRulesConfig, board: Board, layerWinners: List<LayerResult>): List<Int> {
    val moves = ArrayList<Int>()
    for (i in 0 until config.cellCount) {
        if (board[i] != null) continue
        if (layerWinners[config.layerOf(i)].winner != null) continue
        moves.add(i)
    }
    return moves
}

fun getTerminalWinner(config: GameRulesConfig, board: Board, layerWinners: List<LayerResult>): Player? {
    if (!isValidBoardState(config, board) || !isValidLayerResults(config, layerWinners)) return null
    if (config.size == 1) return board[0]
    if (config.is3D) {
        checkCrossLayerWinner(config, board).winner?.let { return it }
        val xWins = layerWinners.count { it.winner == Player.X }
        val oWins = layerWinners.count { it.winner == Player.O }
        if (xWins >= config.matchWinThreshold) return Player.X
        if (oWins >= config.matchWinThreshold) return Player.O
        return null
    }
    return checkBoardWinner(config, board).winner
}

data class MoveResult(
    val board: Board,
    val layerWinners: List<LayerResult>,
    val winner: Player?,
    val draw: Boolean,
    val crossLayerWinningLine: List<Int>?,
    val winningLine: List<Int>?,
    val isXNext: Boolean,
)

/**
 * Plays [index] for whoever is next. Returns null for any illegal move:
 * out of range, occupied, on a claimed layer, or after the game has ended.
 */
fun applyMove(
    config: GameRulesConfig,
    board: Board,
    layerWinners: List<LayerResult>,
    index: Int,
    isXNext: Boolean,
): MoveResult? {
    if (!isValidBoardState(config, board) ||
        !isValidLayerResults(config, layerWinners) ||
        index < 0 || index >= config.cellCount
    ) return null

    if (getTerminalWinner(config, board, layerWinners) != null || !hasLegalMoves(config, board, layerWinners)) {
        return null
    }

    val player = if (isXNext) Player.X else Player.O
    val layerIndex = config.layerOf(index)
    if (board[index] != null || layerWinners[layerIndex].winner != null) return null

    val newBoard = board.toMutableList().also { it[index] = player }
    val newLayerWinners = layerWinners.toMutableList()

    fun result(
        winner: Player?,
        draw: Boolean = false,
        cross: List<Int>? = null,
        line: List<Int>? = null,
    ) = MoveResult(newBoard, newLayerWinners, winner, draw, cross, line, isXNext = !isXNext)

    if (config.size == 1) return result(winner = player, line = listOf(0))

    if (config.is3D) {
        val cross = checkCrossLayerWinner(config, newBoard)
        if (cross.winner != null) return result(winner = cross.winner, cross = cross.line, line = cross.line)

        val layerResult = checkLayerWinner(config, newBoard, layerIndex)
        if (layerResult.winner != null) {
            newLayerWinners[layerIndex] = LayerResult(layerResult.winner, layerResult.line)
        }

        val xWins = newLayerWinners.count { it.winner == Player.X }
        val oWins = newLayerWinners.count { it.winner == Player.O }
        if (xWins >= config.matchWinThreshold) return result(winner = Player.X, line = layerResult.line)
        if (oWins >= config.matchWinThreshold) return result(winner = Player.O, line = layerResult.line)
    } else {
        val boardResult = checkBoardWinner(config, newBoard)
        if (boardResult.winner != null) return result(winner = boardResult.winner, line = boardResult.line)
    }

    // A full board has no legal moves, so this also covers the classic draw.
    if (!hasLegalMoves(config, newBoard, newLayerWinners)) return result(winner = null, draw = true)
    return result(winner = null)
}
